import sys
from math import ceil

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2
    operations = []
    for _ in range(n):
        t = int(input[index])
        x = float(input[index + 1]) / 100000
        y = int(input[index + 2])
        operations.append((t, x, y))
        index += 3

    dp = [-1] * (m + 1)
    dp[0] = 0

    for step in range(1, n + 1):
        new_dp = dp[:]
        for k in range(m + 1):
            if dp[k] == -1:
                continue
            t, x, y = operations[step - 1]
            if t == 1:
                for a in range(y + 1):
                    nk = k + a * x
                    if nk > m:
                        break
                    nk = ceil(nk)
                    if new_dp[nk] == -1 or new_dp[nk] > step:
                        new_dp[nk] = step
            elif t == 2:
                for a in range(y + 1):
                    nk = k * (x ** a)
                    if nk > m:
                        break
                    nk = ceil(nk) if nk != 0 else 0
                    if new_dp[nk] == -1 or new_dp[nk]> step:
                        new_dp[nk] = step
        dp = new_dp

    print(" ".join(map(str, dp[1:])))
main()
